  "servers.settings.publicHelp": "<b>Buono a sapersi:</b> tramite playit.gg o un relay, i giocatori si collegano passando da quel servizio, il che aggiunge un po’ di ritardo, e i ban per IP non funzionano (sembrano arrivare tutti dal servizio). La modalità online tiene comunque fuori gli impostori. La prima volta Windows potrebbe chiedere se Java può usare la rete: consentilo.",
  "servers.settings.tunnel": "Come si collegano gli amici",
  "servers.settings.tunnel.auto": "Automatico",
  "servers.settings.tunnel.playit": "playit.gg",
  "servers.settings.tunnelHint.playit": "Se è collegato un account Microsoft, si prova prima ResinCraft Relay. Altrimenti playit.gg: gratuito e fatto per Minecraft, gli amici ricevono un indirizzo come nome.joinmc.link che resta sempre lo stesso. Al primo avvio ti viene chiesto di collegare ResinCraft a un account playit.gg nel browser (basta un account ospite). Se nessuno dei due funziona, si usa il relay bore.",
  "servers.settings.tunnelHint.relay": "Salta il router. Usalo quando il router dà un indirizzo che gli amici non riescono a raggiungere. L’indirizzo cambia a ogni avvio.",
