  "servers.multicore.open": "Configura",
  "servers.multicore.intro": "Il tick di gioco di Minecraft gira su un solo thread, e queste mod non lo cambiano. Spostano altro lavoro sugli altri core, come costruire i chunk da mostrare a schermo e caricare e generare i chunk, e rendono più leggero il tick stesso.",
