  "servers.multicore.undone": "Annullato. Le mod sono finite nel Cestino.",
  "servers.multicore.reason.vanilla": "Questo è vanilla, che non può eseguire mod. Le mod richiedono un loader di mod come Fabric o NeoForge. ResinCraft non lo converte per te: creane invece uno nuovo con un loader di mod.",
  "servers.multicore.reason.noLoader": "Questo loader è troppo vecchio per queste mod. Richiedono Fabric, Quilt, NeoForge o Forge.",
  "servers.multicore.reason.noMods": "Nessuna di queste mod ha una build per questo loader e questa versione di Minecraft, quindi non c'è nulla da installare.",
  "servers.multicore.reason.plugins": "I plugin non possono rendere il tick multi-core: girano sul thread principale del server. Paper esegue già il lavoro sui chunk su altri core. L'unico modo per far girare il tick stesso su più core è cambiare il software del server in Folia.",
  "servers.multicore.reason.hybrid": "Arclight mescola mod e plugin, e queste mod modificano lo stesso codice che modifica Arclight. Qui non sono sicure, quindi non viene proposto nulla.",
  "servers.multicore.reason.bedrock": "I server Bedrock sono un programma a parte che non può eseguire mod o plugin Java, quindi non c'è nulla da configurare.",
  "servers.multicore.reason.folia": "Questo server usa Folia, che esegue già il tick di regioni diverse del mondo su core diversi.",
  "servers.multicore.reason.noJavaMods": "Questo software del server non può eseguire mod Fabric, Quilt, NeoForge o Forge, quindi non c'è nulla da configurare.",
  "servers.multicore.folia.title": "Passa a Folia (facoltativo)",
